import os, re, json
cwd = os.getcwd()
ev = os.path.join(cwd, 'adb_evidence')
pkgs = json.load(open(os.path.join(ev, 'pkg_list.json'), encoding='utf-8'))

def pmset(mode, user):
    s = set()
    with open(os.path.join(ev, f'pm_list_{mode}_user{user}.txt'), encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line.startswith('package:'):
                s.add(line.split(':', 1)[1].strip())
    return s

dis0 = pmset('-d','0'); en0 = pmset('-e','0')
dis128 = pmset('-d','128'); en128 = pmset('-e','128')

EN_MAP = {'0':'default(enabled)','1':'enabled','2':'disabled','3':'disabled-user','4':'disabled-until-used'}

def parse(path):
    txt = open(path, encoding='utf-8').read()
    if 'Unable to find package' in txt or not txt.strip():
        return None
    # cut at hidden section
    idx = txt.find('Hidden system packages:')
    if idx >= 0:
        txt = txt[:idx]
    ver = None
    m = re.search(r'versionCode=(\\d+)', txt)
    if m: ver = m.group(1)
    users = {}
    for um in re.finditer(r'"'^'"\\s*User (\\d+):(.*)"'$'"', txt, re.M):
        uid, body = um.group(1), um.group(2)
        rec = {}
        for key in ['installed', 'hidden', 'suspended', 'stopped', 'enabled']:
            mm = re.search(r'\\b'+key+r'=(true|false|\\d+)', body)
            if mm: rec[key] = mm.group(1)
        if 'installed' in rec or 'enabled' in rec:
            users[uid] = rec
    return {'version_code': ver, 'users': users}

rows = []
problems = []
for p in pkgs:
    name = p['package']; grp = p['group']
    d = parse(os.path.join(ev, f'dumpsys_{name}.txt'))
    if d is None:
        rows.append({'package': name, 'group': grp, 'error': 'DUMPSYS_FAILED'})
        problems.append((name, 'DUMPSYS_FAILED'))
        continue
    u0 = d['users'].get('0', {})
    u128 = d['users'].get('128', {})
    inst0 = u0.get('installed', 'MISSING_FIELD')
    inst128 = u128.get('installed', 'MISSING_FIELD')
    en0 = u0.get('enabled', 'MISSING_FIELD')
    en128 = u128.get('enabled', 'MISSING_FIELD')
    # effective state: pm list membership is authoritative per user
    eff0 = 'disabled' if name in dis0 else ('enabled' if name in en0 else 'NOT_INSTALLED_OR_UNLISTED')
    eff128 = 'disabled' if name in dis128 else ('enabled' if name in en128 else 'NOT_INSTALLED_OR_UNLISTED')
    rows.append({
        'package': name, 'group': grp, 'version_code': d['version_code'],
        'installed_u0': inst0, 'enabled_flag_u0': en0, 'eff_u0': eff0,
        'installed_u128': inst128, 'enabled_flag_u128': en128, 'eff_u128': eff128,
    })
    # consistency checks
    if inst0 == 'true' and eff0 == 'disabled':
        problems.append((name, 'INSTALLED_U0_BUT_DISABLED'))
    if inst0 == 'true' and eff0 == 'NOT_INSTALLED_OR_UNLISTED':
        problems.append((name, 'INSTALLED_U0_BUT_UNLISTED'))
    if inst128 == 'true' and eff128 == 'disabled':
        problems.append((name, 'INSTALLED_U128_BUT_DISABLED'))
    if name in dis0: problems.append((name, 'IN_PM_DISABLED_U0'))
    if name in dis128: problems.append((name, 'IN_PM_DISABLED_U128'))

