import os, re, json
cwd = os.getcwd()
ev = os.path.join(cwd, 'adb_evidence')
pkgs = json.load(open(os.path.join(ev, 'pkg_list.json'), encoding='utf-8'))

def pmset(mode, user):
    s = set()
    with open(os.path.join(ev, f'pm_list_{mode}_user{user}.txt'), encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line.startswith('package:'):
                s.add(line.split(':', 1)[1].strip())
    return s

PM_DIS_0 = pmset('-d','0'); PM_EN_0 = pmset('-e','0')
PM_DIS_128 = pmset('-d','128'); PM_EN_128 = pmset('-e','128')

def parse(path):
    txt = open(path, encoding='utf-8').read()
    if 'Unable to find package' in txt or not txt.strip():
        return None
    idx = txt.find('Hidden system packages:')
    if idx >= 0:
        txt = txt[:idx]
    ver = None
    m = re.search(r'versionCode=(\\d+)', txt)
    if m: ver = m.group(1)
    users = {}
    for um in re.finditer(r'"'^'"\\s*User (\\d+):(.*)"'$'"', txt, re.M):
        uid, body = um.group(1), um.group(2)
        rec = {}
        for key in ['installed', 'hidden', 'suspended', 'stopped', 'enabled']:
            mm = re.search(r'\\b'+key+r'=(true|false|\\d+)', body)
            if mm: rec[key] = mm.group(1)
        if 'installed' in rec or 'enabled' in rec:
            users[uid] = rec
    return {'version_code': ver, 'users': users}

rows, problems = [], []
for p in pkgs:
    name, grp = p['package'], p['group']
    d = parse(os.path.join(ev, f'dumpsys_{name}.txt'))
    if d is None:
        rows.append({'package': name, 'group': grp, 'error': 'DUMPSYS_FAILED'})
        problems.append((name, 'DUMPSYS_FAILED'))
        continue
    u0 = d['users'].get('0', {}); u128 = d['users'].get('128', {})
    inst0 = u0.get('installed', 'MISSING_FIELD'); inst128 = u128.get('installed', 'MISSING_FIELD')
    flg0 = u0.get('enabled', 'MISSING_FIELD'); flg128 = u128.get('enabled', 'MISSING_FIELD')
    eff0 = 'disabled' if name in PM_DIS_0 else ('enabled' if name in PM_EN_0 else 'NOT_LISTED')
    eff128 = 'disabled' if name in PM_DIS_128 else ('enabled' if name in PM_EN_128 else 'NOT_LISTED')
    rows.append({
        'package': name, 'group': grp, 'version_code': d['version_code'],
        'installed_u0': inst0, 'enabled_flag_u0': flg0, 'eff_u0': eff0,
        'installed_u128': inst128, 'enabled_flag_u128': flg128, 'eff_u128': eff128,
        'pm_dis_u0': 'Y' if name in PM_DIS_0 else 'N',
        'pm_dis_u128': 'Y' if name in PM_DIS_128 else 'N',
    })
    if name in PM_DIS_0: problems.append((name, 'IN_PM_DISABLED_U0'))
    if name in PM_DIS_128: problems.append((name, 'IN_PM_DISABLED_U128'))
    if inst0 == 'true' and eff0 == 'NOT_LISTED': problems.append((name, 'INSTALLED_U0_BUT_NOT_IN_EN_OR_DIS'))
    if inst128 == 'true' and eff128 == 'NOT_LISTED': problems.append((name, 'INSTALLED_U128_BUT_NOT_IN_EN_OR_DIS'))
    if inst0 == 'true' and eff0 == 'disabled': problems.append((name, 'DISABLED_U0'))

json.dump(rows, open(os.path.join(ev, 'parsed.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
print('rows:', len(rows), '| problems:', problems)

# summary stats
not_en_u0 = [r['package'] for r in rows if r.get('eff_u0') "'!= '"'enabled']
print('not enabled in u0:', not_en_u0)
dis_u128 = [r['package'] for r in rows if r.get('eff_u128') == 'disabled']
print('disabled in u128:', dis_u128)
inst_u128 = [r['package'] for r in rows if r.get('installed_u128') == 'true']
